/* @lc app=leetcode id=3017 lang=kotlin */ class Solution { fun ad(D: LongArray, lo: Int, hi: Int, w: Long) = minOf(hi, D.size - 3).let { h -> if (lo <= h) D.set(lo, D[lo] + w).also { D[h + 1] -= w } else Unit } fun countOfPairs(n: Int, x0: Int, y0: Int): LongArray = minOf(x0, y0).let { x -> maxOf(x0, y0).let { y -> if (x == y) LongArray(n) { 2L * (n - 1 - it) } else (y - x + 1).let { m -> (x - 1).let { L -> (n - y).let { R -> LongArray(n + 3).let { D -> (1 until L).forEach { ad(D, it, it, (L - it).toLong()) }.let { (1 until R).forEach { ad(D, it, it, (R - it).toLong()) } }.let { (1..(m - 1) / 2).forEach { ad(D, it, it, m.toLong()) } }.let { if (m % 2 == 0) ad(D, m / 2, m / 2, (m / 2).toLong()) }.let { listOf(L, R).forEach { T -> (1..T).forEach { a -> ad(D, a, a, 1L).let { ad(D, a + 1, a + (m - 1) / 2, 2L) }.let { if (m % 2 == 0) ad(D, a + m / 2, a + m / 2, 1L) } } } }.let { (1..L).forEach { a -> ad(D, a + 2, a + 1 + R, 1L) } }.let { D.runningFold(0L) { s, v -> s + v }.let { pre -> LongArray(n) { 2L * pre[it + 2] } } } } } } } } } }